// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {
        address rewardToken = address(1);
        c.addReward(rewardToken);
        address nonOwner = address(0x123);
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", nonOwner));
        bool diverges = (c.owner() == nonOwner);
        assertTrue(!diverges, "Bug: owner changed after unauthorized transferOwnership");
    }
}
